def _insert(vid, beats):
    bs = L[vid]["beats"]; i = max(k for k, b in enumerate(bs) if b["v"] == "chapter")  # before the Verdict chapter
    n = sum(1 for b in bs if b["v"] == "chapter")
    for b in beats:
        if b["v"] == "chapter":
            b["d"]["num"] = n; n += 1
    bs[i:i] = beats
    bs[i + len(beats)]["d"]["num"] = n

